config/eve-inmp441-overlay.dts:
/dts-v1/;
/plugin/;

/* Pi 4 capture-only I2S card, separate from the analogue playback card.
 * INMP441 has no control bus. The in-tree ADAU7002 codec supplies a passive
 * stereo-I2S ALSA endpoint; it does not imply that an ADAU7002 chip is fitted.
 * config/alsa-inmp441.conf fixes the 64-clock frame required by INMP441.
 * Hardware acceptance (both channels, level and speech) is still required.
 */
/ {
    compatible = "brcm,bcm2711";

    fragment@0 {
        target = <&i2s>;
        __overlay__ { status = "okay"; };
    };

    fragment@1 {
        target-path = "/";
        __overlay__ {
            eve_mic_codec: eve-mic-codec {
                compatible = "adi,adau7002";
                #sound-dai-cells = <0>;
                status = "okay";
            };

            eve-mic-sound {
                compatible = "simple-audio-card";
                simple-audio-card,name = "EVEINMP441";
                simple-audio-card,format = "i2s";
                simple-audio-card,bitclock-master = <&eve_mic_cpu>;
                simple-audio-card,frame-master = <&eve_mic_cpu>;
                simple-audio-card,widgets = "Microphone", "Microphone Jack";
                simple-audio-card,routing = "PDM_DAT", "Microphone Jack";
                status = "okay";

                eve_mic_cpu: simple-audio-card,cpu { sound-dai = <&i2s>; };
                simple-audio-card,codec { sound-dai = <&eve_mic_codec>; };
            };
        };
    };
};

eve:
#!/usr/bin/env bash
# One short command for everything.  Usage:  ./eve <word> [more]
#   run | sim | face | stage [M04] [done] | status [full] | ctl <command> [key=value] | cfg ... | doctor
#   i2c | cliff floor|edge|apply | mic | flash | test | estop
cd "$(dirname "$0")" || exit 1
PY=.venv/bin/python; [ -x "$PY" ] || PY=python3
word="${1:-help}"; shift 2>/dev/null
case "$word" in
  run)    exec "$PY" -m eve3 "$@" ;;
  sim)    exec "$PY" -m eve3 --sim "$@" ;;
  face)   setsid nohup bash scripts/face_kiosk.sh >/dev/null 2>&1 & echo "Face started on the Pi screen." ;;
  stage)  exec "$PY" tools/stage.py "$@" ;;
  status) exec "$PY" tools/evectl.py status "$@" ;;
  estop)  exec "$PY" tools/evectl.py estop ;;
  ctl)    exec "$PY" tools/evectl.py "$@" ;;
  cfg)    exec "$PY" tools/evecfg.py "$@" ;;
  doctor) exec "$PY" tools/doctor.py ;;
  i2c)    exec "$PY" tools/i2c_diag.py ;;
  cliff)  exec "$PY" tools/calibrate_cliff.py "$@" ;;
  mic)    exec "$PY" tools/mic_level.py ;;
  flash)  exec bash scripts/flash_mega.sh "$@" ;;
  test)   exec "$PY" -m unittest discover -s tests -t . "$@" ;;
  *)      sed -n '2,5p' "$0" ;;
esac

