eve3/home/store.py:
"""Bounded private records for deliberately saved home activities."""
from __future__ import annotations

import json
import os
from pathlib import Path
import sqlite3
import threading
import time


class HomeStore:
    KINDS = frozenset({"story", "recipe", "message", "capsule"})

    def __init__(self, path):
        path = Path(path)
        path.parent.mkdir(parents=True, exist_ok=True)
        self.lock = threading.RLock()
        fd = os.open(path, os.O_CREAT | os.O_RDWR, 0o600)
        os.close(fd)
        os.chmod(path, 0o600)
        self.db = sqlite3.connect(path, check_same_thread=False, timeout=.2)
        self.db.execute("PRAGMA secure_delete=ON")
        self.db.execute("CREATE TABLE IF NOT EXISTS records ("
                        "id INTEGER PRIMARY KEY AUTOINCREMENT, kind TEXT NOT NULL, "
                        "body TEXT NOT NULL, updated REAL NOT NULL)")
        self.db.commit()

    def save(self, kind, value, record_id=None):
        if kind not in self.KINDS:
            raise ValueError("unknown record kind")
        body = json.dumps(value, ensure_ascii=False, allow_nan=False)
        if len(body.encode("utf-8")) > 16000:
            raise ValueError("record too large")
        with self.lock, self.db:
            if record_id is not None:
                if type(record_id) is not int or record_id <= 0:
                    raise ValueError("invalid record id")
                cursor = self.db.execute("UPDATE records SET body=?,updated=? WHERE id=? AND kind=?",
                                         (body, time.time(), record_id, kind))
                if cursor.rowcount != 1:
                    raise ValueError("record not found")
                return record_id
            if self.db.execute("SELECT COUNT(*) FROM records").fetchone()[0] >= 300:
                raise ValueError("home record limit reached; delete an old entry")
            return self.db.execute("INSERT INTO records(kind,body,updated) VALUES(?,?,?)",
                                   (kind, body, time.time())).lastrowid

    def list(self, kind):
        with self.lock:
            rows = self.db.execute("SELECT id,body,updated FROM records WHERE kind=? ORDER BY id DESC LIMIT 300", (kind,)).fetchall()
            return [{"id": row[0], "value": json.loads(row[1]), "updated": row[2]} for row in rows]

    def get(self, kind, record_id):
        if type(record_id) is not int or record_id <= 0:
            raise ValueError("invalid record id")
        return next((r for r in self.list(kind) if r["id"] == record_id), None)

    def delete(self, kind, record_id):
        if kind not in self.KINDS or type(record_id) is not int or record_id <= 0:
            raise ValueError("invalid record")
        with self.lock, self.db:
            return self.db.execute("DELETE FROM records WHERE kind=? AND id=?", (kind, record_id)).rowcount > 0

    def counts(self):
        with self.lock:
            return dict(self.db.execute("SELECT kind,COUNT(*) FROM records GROUP BY kind").fetchall())

    def clear(self):
        with self.lock, self.db:
            self.db.execute("DELETE FROM records")

    def close(self):
        with self.lock:
            self.db.close()

eve3/integrations.py:
"""M16 - optional read-only internet look-ups. OFF by default (integrations.web_tools_enabled).
A fixed allow-list; only the short search word goes out - never audio, images, memory or names."""
from __future__ import annotations
import json, re, urllib.parse, urllib.request

UA = "EVE-home-robot/3"


def _json(url: str, timeout=5.0):
    request = urllib.request.Request(url, headers={"User-Agent": UA})
    with urllib.request.urlopen(request, timeout=timeout) as response:
        raw = response.read(65537)
    if len(raw) > 65536:
        raise ValueError("response too large")
    return json.loads(raw)


def _term(value, limit=60) -> str:
    value = " ".join(str(value).split())
    if not value or len(value) > limit or not re.fullmatch(r"[\w .'ऀ-ॿ-]+", value):
        raise ValueError("search word not accepted")
    return value


def wikipedia(term, fetch=_json) -> str:
    data = fetch("https://en.wikipedia.org/api/rest_v1/page/summary/" + urllib.parse.quote(_term(term), safe=""))
    return " ".join(str(data.get("extract", "")).split())[:400]


def exchange_rate(base="USD", quote="INR", fetch=_json) -> float | None:
    base, quote = str(base).upper(), str(quote).upper()
    if not (re.fullmatch(r"[A-Z]{3}", base) and re.fullmatch(r"[A-Z]{3}", quote)):
        raise ValueError("currency codes are three letters")
    rate = fetch(f"https://open.er-api.com/v6/latest/{base}").get("rates", {}).get(quote)
    return float(rate) if type(rate) in (int, float) else None


TOOLS = {"wikipedia": wikipedia, "exchange_rate": exchange_rate}


def call(cfg: dict, name: str, *args):
    if cfg["integrations"]["web_tools_enabled"] is not True:
        raise PermissionError("web tools are switched off")
    if name not in TOOLS:
        raise KeyError(name)
    return TOOLS[name](*args)

