"""Offline command understanding for English, Hindi and Marathi (Devanagari or typed in English letters).
Only the person's own words are parsed here - never text produced by an AI model."""
from __future__ import annotations
import re
from dataclasses import dataclass, field

_DEV_DIGITS = str.maketrans("०१२३४५६७८९", "0123456789")
_PUNCT = re.compile(r"[^\w\sऀ-ॿ:]", re.UNICODE)


@dataclass(frozen=True)
class Intent:
    name: str
    args: dict = field(default_factory=dict)


def normalize(text: str) -> str:
    return " ".join(_PUNCT.sub(" ", str(text).lower().translate(_DEV_DIGITS)).split())


def strip_wake(text: str, wake_words) -> tuple[bool, str]:
    """Returns (wake word heard, remaining words). The wake word may come with 'hey/hi/ok/अरे/ए'."""
    words = normalize(text).split()
    wake = {normalize(w) for w in wake_words}
    for i, w in enumerate(words[:4]):
        if w in wake:
            return True, " ".join(words[i + 1:])
        if w not in {"hey", "hi", "ok", "okay", "अरे", "ए"}:
            break
    return False, " ".join(words)


# (intent, words/phrases). Checked in order; STOP is first so it always wins.
_RULES = [
    ("stop", ["stop", "halt", "freeze", "ruk", "ruko", "ruk ja", "bas", "thamb", "thamba", "रुक", "रुको", "रुक जा", "बस", "थांब", "थांबा"]),
    ("cancel_reminders", ["cancel reminder", "cancel reminders", "cancel timer", "रिमाइंडर रद्द", "आठवण रद्द"]),
    ("remind", ["remind", "reminder", "yaad dila", "yaad dilana", "aathvan", "athavan", "याद दिला", "याद दिलाना", "आठवण"]),
    ("timer", ["timer", "टाइमर", "टायमर"]),
    ("forget_hint", ["forget everything", "erase memory", "सब भूल जा", "सगळं विसर"]),
    ("recall", ["what do you remember", "what did i tell you", "kya yaad hai", "kay athavte", "क्या याद है", "काय आठवते", "काय लक्षात आहे"]),
    ("remember", ["remember that", "remember", "yaad rakh", "yaad rakhna", "lakshat thev", "याद रख", "याद रखना", "लक्षात ठेव"]),
    ("turn_left", ["turn left", "go left", "baye mud", "baen mud", "davikade val", "बाएं मुड़", "बाएँ मुड़", "डावीकडे वळ"]),
    ("turn_right", ["turn right", "go right", "daye mud", "daen mud", "ujvikade val", "दाएं मुड़", "दाएँ मुड़", "उजवीकडे वळ"]),
    ("forward", ["go forward", "move forward", "come forward", "forward", "come here", "aage", "aage chal", "aage aa", "pudhe", "pudhe ye",
                 "pudhe ja", "आगे", "आगे चल", "आगे आ", "पुढे", "पुढे ये", "पुढे जा", "इधर आ", "इकडे ये"]),
    ("look_left", ["look left", "baye dekh", "davikade bagh", "बाएं देख", "बाएँ देख", "डावीकडे बघ"]),
    ("look_right", ["look right", "daye dekh", "ujvikade bagh", "दाएं देख", "दाएँ देख", "उजवीकडे बघ"]),
    ("look_up", ["look up", "upar dekh", "var bagh", "ऊपर देख", "वर बघ"]),
    ("look_down", ["look down", "niche dekh", "khali bagh", "नीचे देख", "खाली बघ"]),
    ("look_center", ["look at me", "look straight", "look center", "look centre", "saamne dekh", "samor bagh", "सामने देख", "समोर बघ", "मेरी तरफ देख", "माझ्याकडे बघ"]),
    ("sleep", ["go to sleep", "sleep", "so ja", "zop", "zopa", "सो जा", "झोप", "झोपा"]),
    ("wake", ["wake up", "uth", "uth ja", "utha", "उठ", "उठ जा", "उठा", "जाग"]),
    ("time", ["what time", "time", "kitne baje", "samay", "kiti vajle", "vel kay", "कितने बजे", "समय", "किती वाजले", "वेळ"]),
    ("date", ["what date", "what day", "date", "today", "aaj kya", "tarikh", "aaj kay", "आज क्या", "तारीख", "आज काय", "आज कोणता"]),
    ("joke", ["joke", "chutkula", "vinod", "चुटकुला", "जोक", "विनोद"]),
    ("story", ["story", "kahani", "goshta", "gosht", "कहानी", "गोष्ट"]),
    ("who", ["who are you", "your name", "tum kaun", "tumhara naam", "tu kon", "tuza nav", "तुम कौन", "तुम्हारा नाम", "तू कोण", "तुझं नाव", "तुझे नाव"]),
    ("how", ["how are you", "kaise ho", "kaisi ho", "kasa ahes", "kashi ahes", "कैसे हो", "कैसी हो", "कसा आहेस", "कशी आहेस"]),
    ("status", ["are you ok", "status", "battery", "sab theek", "sagla thik", "सब ठीक", "बैटरी", "सगळं ठीक"]),
    ("thanks", ["thank you", "thanks", "dhanyavad", "shukriya", "धन्यवाद", "शुक्रिया", "आभारी"]),
    ("bye", ["bye", "good night", "alvida", "shubh ratri", "अलविदा", "शुभ रात्रि", "शुभ रात्री", "टाटा"]),
    ("greet", ["hello", "hi", "hey", "namaste", "namaskar", "good morning", "नमस्ते", "नमस्कार", "हेलो", "हाय"]),
]
_UNITS = [(3600, r"hours?|hrs?|ghante|ghanta|taas|tasa|घंटे|घंटा|तास"),
          (60, r"minutes?|mins?|minat|minit|मिनट|मिनिट|मिनिटे|मिनिटांनी|मिनिटं"),
          (1, r"seconds?|secs?|sekand|सेकंड|सेकंद")]
_FILLER = re.compile(r"^(?:me |mujhe |mala |मुझे |मला )?(?:in |after |to |that |ki |ke |baad |bad |nantar |kar |kara |de |dena |बाद |नंतर |की |कि |के |कर |करा |दे |देना )*")
_EXACT_RULES = {"forward", "turn_left", "turn_right", "look_left", "look_right", "look_up", "look_down",
                "look_center", "sleep", "wake", "cancel_reminders", "recall"}


def _has(text: str, phrase: str) -> bool:
    return re.search(rf"(?<![\wऀ-ॿ]){re.escape(phrase)}(?![\wऀ-ॿ])", text) is not None


def _duration(text: str):
    """First '<number> <unit>' in the text -> (seconds, text without it)."""
    for scale, unit in _UNITS:
        m = re.search(rf"(\d{{1,4}})\s*(?:{unit})(?![\wऀ-ॿ])", text)
        if m:
            return int(m[1]) * scale, " ".join((text[:m.start()] + " " + text[m.end():]).split())
    return None, text


def _after(text: str, phrases) -> str:
    for phrase in sorted(phrases, key=len, reverse=True):
        m = re.search(rf"(?<![\wऀ-ॿ]){re.escape(phrase)}(?![\wऀ-ॿ])", text)
        if m:
            before, after = text[:m.start()].strip(), text[m.end():].strip()
            rest = after or before                      # Hindi/Marathi put the verb last
            return _FILLER.sub("", rest + " ").strip()
    return text


def parse(text: str) -> Intent | None:
    t = normalize(text)
    if not t:
        return None
    command = t.removeprefix("please ").removesuffix(" please")
    for name, phrases in _RULES:
        if name in _EXACT_RULES:
            if command in phrases:
                return Intent(name)
            continue
        if name == "remember" and not any(command == p or command.startswith(p + " ") for p in phrases):
            continue
        if not any(_has(t, p) for p in phrases):
            continue
        if name in ("remind", "timer"):
            seconds, rest = _duration(t)
            if seconds is None:
                return Intent("remind_unclear")
            what = _after(rest, phrases) if name == "remind" else ""
            return Intent("remind", {"seconds": seconds, "text": what or "timer"})
        if name == "remember":
            what = _after(t, phrases)
            return Intent("remember", {"text": what}) if what else Intent("remember_unclear")
        return Intent(name)
    return None

eve3/mega_link.py:
"""M02 - single owner of the Mega serial port: SYNC, correlated ACKs, heartbeats, telemetry."""
from __future__ import annotations
import glob, threading, time
from .protocol import MAX_FRAME, decode, encode, parse_telemetry

BY_ID_GLOB = "/dev/serial/by-id/usb-1a86_USB*"       # CH340 on the Mega clone


def find_port(configured: str | None) -> str:
    # An explicit setting must win, especially when more than one USB serial board is attached.
    if configured:
        return configured
    hits = sorted(glob.glob(BY_ID_GLOB))
    if len(hits) > 1:
        raise ValueError("Multiple serial boards found; set serial.port to the Mega's by-id path")
    return hits[0] if hits else "/dev/ttyUSB0"


def open_serial(port: str, baud: int = 115200):
    import serial                                     # pyserial, imported only on the robot
    return serial.Serial(port, baud, timeout=0.08, write_timeout=0.15)


class MegaLink:
    def __init__(self, opener, expected_id: str = "", ack_timeout_s: float = 0.25,
                 hb_max_age_s: float = 0.35, telemetry_max_age_s: float = 0.5, on_telemetry=None):
        self._opener = opener                         # callable -> object with read_until/write/close
        self.expected_id = expected_id
        self.ack_timeout_s = ack_timeout_s
        self.hb_max_age_s, self.telemetry_max_age_s = hb_max_age_s, telemetry_max_age_s
        self.on_telemetry = on_telemetry
        self.ser = None
        self.seq = 1
        self.synced = False
        self.synced_at = 0.0
        self.firmware_id = ""
        self.telemetry: dict = {}
        self.telemetry_at = 0.0
        self.hb_ack_at = 0.0
        self.last_error = "not opened"
        self._stop = threading.Event()
        self._thread = None
        self._wlock = threading.RLock()
        self._slock = threading.RLock()
        self._pending: dict[int, tuple[threading.Event, list]] = {}
        self._hb: dict[int, float] = {}

    # -- lifecycle ---------------------------------------------------------
    def open(self, settle_s: float = 2.0):
        self.close()
        self.ser = self._opener()
        self.seq, self.synced, self.last_error = 1, False, ""
        self.telemetry, self.telemetry_at, self.hb_ack_at = {}, 0.0, 0.0
        self._stop.clear()
        if settle_s and self._stop.wait(settle_s):    # opening the port resets the Mega; let it boot
            return
        try:
            self.ser.reset_input_buffer()
        except Exception:
            pass
        self._thread = threading.Thread(target=self._reader, name="eve3-mega-rx", daemon=True)
        self._thread.start()
        try:
            ack = self.request("SYNC", timeout_s=0.6)
            self.firmware_id = ack.split(",", 1)[1] if "," in ack else ""
            self.synced_at = time.monotonic()
            self.synced = True
        except Exception as exc:
            self.close()
            self.last_error = f"SYNC failed: {exc}"
            raise

    def close(self):
        if self.ser is not None:
            try:
                self._send("STOP")
            except Exception:
                pass
        self._stop.set()
        self.synced = False
        with self._wlock:
            ser, self.ser = self.ser, None
        if ser is not None:
            try:
                ser.close()
            except Exception:
                pass
        with self._slock:
            for event, box in self._pending.values():
                box.append("ERR,CLOSED")
                event.set()
            self._pending.clear()
            self._hb.clear()
        if self._thread and self._thread is not threading.current_thread():
            self._thread.join(timeout=1)
        self._thread = None

    # -- state -------------------------------------------------------------
    def online(self, now: float | None = None) -> bool:
        now = time.monotonic() if now is None else now
        return bool(self.synced and self.ser is not None
                    and 0 < self.hb_ack_at and now - self.hb_ack_at < self.hb_max_age_s
                    and 0 < self.telemetry_at and now - self.telemetry_at < self.telemetry_max_age_s)

    @property
    def firmware_ok(self) -> bool:
        return bool(self.synced and self.expected_id and self.firmware_id == self.expected_id)

    # -- tx ----------------------------------------------------------------
    def _send(self, payload, pending=None, heartbeat=False) -> int:
        with self._wlock:
            if self.ser is None:
                raise RuntimeError("Mega not open")
            seq = self.seq
            self.seq = (seq + 1) & 0xFFFF or 1
            with self._slock:
                if pending:
                    self._pending[seq] = pending
                if heartbeat:
                    now = time.monotonic()
                    self._hb = {s: t for s, t in self._hb.items() if now - t < 1}
                    self._hb[seq] = now
            try:
                data = encode(seq, payload)
                if self.ser.write(data) != len(data):
                    raise IOError("short serial write")
            except Exception:
                with self._slock:
                    self._pending.pop(seq, None)
                    self._hb.pop(seq, None)
                raise
            return seq

    def request(self, payload, timeout_s=None) -> str:
        """Send and wait for the ACK carrying the same sequence number. Raises on ERR or timeout."""
        timeout_s = self.ack_timeout_s if timeout_s is None else timeout_s
        pending = (threading.Event(), [])
        seq = self._send(payload, pending=pending)
        try:
            if not pending[0].wait(timeout_s):
                raise TimeoutError(f"no ACK for {payload.split(',')[0]}")
            reply = pending[1][0]
            if not (reply == "ACK" or reply.startswith("ACK,")):
                raise RuntimeError(reply)
            return reply
        finally:
            with self._slock:
                self._pending.pop(seq, None)

    def heartbeat(self):
        self._send("HB", heartbeat=True)

    def drive(self, left: int, right: int):
        self._send(f"DRIVE,{int(left)},{int(right)}")

    def stop_motion(self):
        self._send("DRIVE,0,0")

    def emergency_stop(self):
        self._send("STOP")

    def head(self, pan: int, tilt: int):
        self._send(f"HEAD,{int(pan)},{int(tilt)}")

    def clear_stop(self):
        return self.request("CLEAR")

    def set_manual_home(self):
        return self.request("HOMESET")

    def release_head(self):
        self._send("HEADSTOP")

    # -- rx ----------------------------------------------------------------
    def _consume(self, line: bytes):
        seq, payload = decode(line)
        now = time.monotonic()
        if payload == "ACK" or payload.startswith(("ACK,", "ERR,")):
            with self._slock:
                sent = self._hb.pop(seq, None)
                if sent is not None and payload == "ACK" and 0 <= now - sent <= self.ack_timeout_s:
                    self.hb_ack_at = now
                pending = self._pending.get(seq)
                if pending:
                    pending[1].append(payload)
                    pending[0].set()
        elif payload.startswith("T,"):
            self.telemetry = parse_telemetry(payload)
            self.telemetry_at = now
            if self.on_telemetry:
                self.on_telemetry(self.telemetry, now)

    def _reader(self):
        buf, discarding = bytearray(), False
        ser = self.ser
        while not self._stop.is_set() and ser is not None:
            try:
                chunk = ser.read_until(b"\n", MAX_FRAME + 1)
                if not chunk:
                    continue
                if not discarding:
                    buf.extend(chunk)
                    if len(buf) > MAX_FRAME:
                        buf.clear()
                        discarding = True
                if not chunk.endswith(b"\n"):
                    continue
                if discarding:
                    discarding = False
                    continue
                frame = bytes(buf)
                buf.clear()
                try:
                    self._consume(frame)
                except (ValueError, UnicodeError):
                    continue                           # corrupt frame: ignore, never guess
            except Exception as exc:
                if not self._stop.is_set():
                    self.last_error = f"serial read failed: {type(exc).__name__}"
                    self.synced = False
                return

eve3/memory.py:
"""M11 - local memory in one SQLite file on the Pi. Nothing here ever leaves the device.
Notes are stored only with explicit consent ("remember that ..."). Conversations are not stored."""
from __future__ import annotations
import os, sqlite3, threading, time
from pathlib import Path

MAX_TEXT = 300


def clean_text(text, limit=MAX_TEXT) -> str:
    if not isinstance(text, str):
        raise ValueError("text required")
    text = " ".join("".join(ch if ch.isprintable() else " " for ch in text).split())
    if not text or len(text) > limit:
        raise ValueError(f"text must be 1..{limit} characters")
    return text


class Memory:
    def __init__(self, path: str | Path, max_notes: int = 500):
        self.path, self.max_notes = str(path), max_notes
        if self.path != ":memory:":
            Path(self.path).parent.mkdir(parents=True, exist_ok=True, mode=0o700)
        self._db = sqlite3.connect(self.path, check_same_thread=False)
        self._lock = threading.Lock()
        if self.path != ":memory:":
            try:
                os.chmod(self.path, 0o600)
            except OSError:
                pass
        with self._lock, self._db:
            self._db.executescript(
                "CREATE TABLE IF NOT EXISTS notes(id INTEGER PRIMARY KEY, text TEXT NOT NULL, created REAL NOT NULL);"
                "CREATE TABLE IF NOT EXISTS reminders(id INTEGER PRIMARY KEY, due REAL NOT NULL, text TEXT NOT NULL,"
                " done INTEGER NOT NULL DEFAULT 0, announced INTEGER NOT NULL DEFAULT 0);"
                "CREATE TABLE IF NOT EXISTS kv(key TEXT PRIMARY KEY, value TEXT NOT NULL);")
            if not any(col[1] == "announced" for col in self._db.execute("PRAGMA table_info(reminders)")):
                self._db.execute("ALTER TABLE reminders ADD COLUMN announced INTEGER NOT NULL DEFAULT 0")

    def _q(self, sql, args=()):
        with self._lock, self._db:
            return self._db.execute(sql, args).fetchall()

    # -- notes ---------------------------------------------------------------
    def add_note(self, text, consent) -> int:
        if consent is not True:
            raise PermissionError("a note is saved only when the person clearly asks EVE to remember it")
        text = clean_text(text)
        if self._q("SELECT COUNT(*) FROM notes")[0][0] >= self.max_notes:
            raise ValueError("memory is full; forget some notes first")
        with self._lock, self._db:
            return self._db.execute("INSERT INTO notes(text, created) VALUES(?, ?)", (text, time.time())).lastrowid

    def notes(self, limit=20) -> list[dict]:
        return [{"id": i, "text": t} for i, t in self._q("SELECT id, text FROM notes ORDER BY id DESC LIMIT ?", (int(limit),))]

    def forget_note(self, note_id) -> bool:
        with self._lock, self._db:
            return self._db.execute("DELETE FROM notes WHERE id=?", (int(note_id),)).rowcount > 0

    # -- reminders -----------------------------------------------------------
    def add_reminder(self, due_epoch: float, text) -> int:
        text = clean_text(text, 200)
        if self._q("SELECT COUNT(*) FROM reminders WHERE done=0")[0][0] >= 50:
            raise ValueError("too many reminders waiting")
        with self._lock, self._db:
            return self._db.execute("INSERT INTO reminders(due, text) VALUES(?, ?)", (float(due_epoch), text)).lastrowid

    def pending_reminders(self) -> list[dict]:
        return [{"id": i, "due": d, "text": t, "announced": bool(a)}
                for i, d, t, a in self._q("SELECT id, due, text, announced FROM reminders WHERE done=0 ORDER BY due, id")]

    def next_due(self, now: float) -> dict | None:
        rows = self._q("SELECT id, due, text FROM reminders WHERE done=0 AND announced=0 AND due<=? ORDER BY due, id LIMIT 1", (now,))
        if rows:
            ident, due, text = rows[0]
            return {"id": ident, "due": due, "text": text}
        return None

    def mark_announced(self, reminder: dict):
        # Match the original item even if an erase happened during playback.
        self._q("UPDATE reminders SET announced=1 WHERE id=? AND done=0 AND due=? AND text=?",
                (reminder["id"], reminder["due"], reminder["text"]))

    def cancel_reminder(self, ident: int) -> bool:
        with self._lock, self._db:
            return self._db.execute("UPDATE reminders SET done=1 WHERE id=? AND done=0", (ident,)).rowcount > 0

    def cancel_reminders(self) -> int:
        with self._lock, self._db:
            return self._db.execute("UPDATE reminders SET done=1 WHERE done=0").rowcount

    # -- small counters (for example the cloud daily limit) ------------------------
    def get(self, key, default=None):
        rows = self._q("SELECT value FROM kv WHERE key=?", (key,))
        return rows[0][0] if rows else default

    def put(self, key, value):
        self._q("INSERT INTO kv(key, value) VALUES(?, ?) ON CONFLICT(key) DO UPDATE SET value=excluded.value", (key, str(value)))

    def erase_all(self):
        with self._lock, self._db:
            self._db.executescript("DELETE FROM notes; DELETE FROM reminders; DELETE FROM kv;")
        with self._lock:
            self._db.execute("VACUUM")

    def close(self):
        with self._lock:
            self._db.close()

eve3/motion.py:
"""M07 drive and M08 head. Nothing here talks to the Mega without a passing SafetyGate verdict.

Drive: forward and gentle arcs only; reverse and pivot are refused unless the owner enables them
(there is no rear/pivot cliff coverage). A move lasts at most `move_max_seconds` and is re-checked
every control tick; the Mega additionally stops by itself if commands stop arriving.
Head: owner aligns the printed centre marks and confirms "home"; before limits are verified only
small single-axis jogs are possible."""
from __future__ import annotations
import time


class Drive:
    def __init__(self, cfg, link, gate, hub, clock=time.monotonic):
        d = cfg["drive"]
        self.link, self.gate, self.hub, self._clock = link, gate, hub, clock
        self.max_pwm, self.test_pwm = int(d["max_pwm"]), int(d["test_pwm"])
        self.test_s, self.max_s = float(d["test_seconds"]), float(d["move_max_seconds"])
        self.reverse_ok, self.pivot_ok = d["reverse_allowed"] is True, d["pivot_allowed"] is True
        self.renew_s = d["command_lease_ms"] / 1000 / 2.5
        self.active = None            # (left, right, deadline, test)
        self._sent_at = 0.0
        self.last_stop_reason = ""

    def move(self, left, right, seconds, test=False) -> tuple[bool, str]:
        if type(left) is not int or type(right) is not int or type(seconds) not in (int, float):
            return False, "numbers required"
        if left == 0 and right == 0:
            self.stop("stop requested")
            return True, "stopped"
        limit_pwm, limit_s = (self.test_pwm, self.test_s) if test else (self.max_pwm, self.max_s)
        if abs(left) > limit_pwm or abs(right) > limit_pwm:
            return False, f"speed limit is {limit_pwm}"
        if not 0 < seconds <= limit_s:
            return False, f"duration must be within {limit_s} s"
        if (left < 0 or right < 0) and not self.reverse_ok:
            return False, "reverse is disabled"
        if (left > 0) != (right > 0) and not self.pivot_ok:
            return False, "pivot turns are disabled"
        verdict = self.gate.drive_verdict(self.hub.snapshot(), self.link, test)
        if not verdict.ok:
            self.stop(verdict.reason)
            return False, verdict.reason
        self.active = (left, right, self._clock() + seconds, test)
        return (True, "moving") if self._send() else (False, self.last_stop_reason)

    def _send(self):
        active = self.active
        if active is None:
            return False
        try:
            self.link.drive(active[0], active[1])
            self._sent_at = self._clock()
            return True
        except Exception as exc:
            self.stop(f"Mega write failed: {type(exc).__name__}")
            return False

    def stop(self, reason=""):
        self.active, self.last_stop_reason = None, reason
        try:
            self.link.stop_motion()
        except Exception:
            pass                          # link down: the Mega's own lease/heartbeat timeout stops the wheels

    def tick(self):
        active = self.active                  # read once: another thread may clear it
        if active is None:
            return
        now = self._clock()
        if now >= active[2]:
            self.stop("move finished")
            return
        verdict = self.gate.drive_verdict(self.hub.snapshot(), self.link, active[3])
        if not verdict.ok:
            self.stop(verdict.reason)
        elif now - self._sent_at >= self.renew_s:
            self._send()


class Head:
    def __init__(self, cfg, link, gate, hub, clock=time.monotonic):
        h = cfg["head"]
        self.link, self.gate, self.hub, self._clock = link, gate, hub, clock
        self.pan_lim = (h["pan_min_steps"], h["pan_max_steps"])
        self.tilt_lim = (h["tilt_min_steps"], h["tilt_max_steps"])
        self.limits_verified = h["soft_limits_verified"] is True
        self.jog_max = int(h["jog_max_steps"])
        self.target = None            # (pan, tilt, deadline, test)
        self._sent_at = 0.0
        self._released = False

    @property
    def homed(self) -> bool:
        return not self._released and self.link.telemetry.get("homed") is True

    def position(self):
        t = self.link.telemetry
        return (t.get("pan"), t.get("tilt")) if self.homed else (None, None)

    def home(self, owner_confirmed) -> tuple[bool, str]:
        if owner_confirmed is not True:
            return False, "align the head centre marks by hand first, then confirm"
        verdict = self.gate.head_verdict(self.hub.snapshot(), self.link, test=True)
        if not verdict.ok:
            return False, verdict.reason
        try:
            self.link.set_manual_home()
        except Exception as exc:
            return False, f"Mega refused home: {exc}"
        self._released = False
        return True, "this position is now the head centre"

    def _start(self, pan, tilt, test):
        if not (self.pan_lim[0] <= pan <= self.pan_lim[1] and self.tilt_lim[0] <= tilt <= self.tilt_lim[1]):
            return False, "outside head limits"
        cur = self.position()
        if not all(type(value) is int for value in cur):
            return False, "head position missing; home the head again"
        steps = abs(pan - cur[0]) + abs(tilt - cur[1])
        self.target = (pan, tilt, self._clock() + steps * 0.002 + 0.5, test)
        return (True, "moving") if self._send() else (False, "Mega head write failed")

    def _send(self):
        target = self.target
        if target is None:
            return False
        try:
            self.link.head(target[0], target[1])
            self._sent_at = self._clock()
            return True
        except Exception:
            self.release()
            return False

    def goto(self, pan, tilt) -> tuple[bool, str]:
        if type(pan) is not int or type(tilt) is not int:
            return False, "whole numbers required"
        if not self.limits_verified:
            return False, "head limits not verified yet; use small jogs"
        verdict = self.gate.head_verdict(self.hub.snapshot(), self.link)
        if not verdict.ok:
            return False, verdict.reason
        if not self.homed:
            return False, "head not homed"
        return self._start(pan, tilt, False)

    def jog(self, dpan, dtilt, clearance_confirmed) -> tuple[bool, str]:
        if clearance_confirmed is not True:
            return False, "check nothing blocks the head and confirm before every jog"
        if type(dpan) is not int or type(dtilt) is not int:
            return False, "whole numbers required"
        if bool(dpan) == bool(dtilt) or max(abs(dpan), abs(dtilt)) > self.jog_max:
            return False, f"jog one axis at a time by 1..{self.jog_max} steps"
        verdict = self.gate.head_verdict(self.hub.snapshot(), self.link, test=True)
        if not verdict.ok:
            return False, verdict.reason
        if not self.homed:
            return False, "head not homed"
        if self.target is not None:
            return False, "head is still moving"
        pan, tilt = self.position()
        return self._start(pan + dpan, tilt + dtilt, True)

    def release(self):
        self.target = None
        self._released = True
        try:
            self.link.release_head()
        except Exception:
            return False                  # the Mega's lease still cuts movement if the link has failed
        return True

    def stop(self):
        if self.target is not None or self.link.telemetry.get("head_busy") is True:
            self.release()

    def tick(self):
        """Renew the Mega's head lease while a move is in progress and still safe."""
        target = self.target                  # read once: another thread may clear it
        if target is None:
            return
        pan, tilt, deadline, test = target
        if self.position() == (pan, tilt):
            self.target = None
        elif self._clock() >= deadline or not self.gate.head_verdict(self.hub.snapshot(), self.link, test).ok or not self.homed:
            self.release()
        elif self._clock() - self._sent_at >= 0.1:
            self._send()

eve3/power.py:
"""M03 - power. Two USB power banks, no electrical monitoring (INA219 removed), so software cannot see
battery level. What it can do: refuse motion until the owner has recorded the M03 measurements, read the
Pi's own under-voltage flag, and limit motion to a short attended session that the owner starts."""
from __future__ import annotations
import re, subprocess, time
from .config import POWER_FLAGS, missing_flags


def read_throttled(run=subprocess.run) -> int | None:
    """Pi firmware supply flags. bit0 = under-voltage now, bit16 = under-voltage since boot. None = unknown."""
    try:
        out = run(["vcgencmd", "get_throttled"], capture_output=True, text=True, timeout=2, check=False).stdout
        m = re.fullmatch(r"throttled=0x([0-9a-fA-F]{1,8})\s*", out)
        return int(m[1], 16) if m else None
    except Exception:
        return None


class PowerSession:
    """An attended session: the owner is present, hand near the Bank B switch. Never saved to disk."""

    def __init__(self, cfg: dict, throttled=read_throttled, clock=time.monotonic):
        self.cfg, self._throttled, self._clock = cfg, throttled, clock
        self.max_minutes = cfg["power"]["session_max_minutes"]
        self.until = 0.0
        self.last_flags: int | None = None
        self.ended_reason = "not started"

    def start(self, minutes) -> tuple[bool, str]:
        if type(minutes) is not int or not 1 <= minutes <= self.max_minutes:
            return False, f"minutes must be 1..{self.max_minutes}"
        missing = missing_flags(self.cfg, POWER_FLAGS)
        if missing:
            return False, "power not verified (M03): " + ", ".join(missing)
        self.last_flags = self._throttled()
        if self.last_flags is None:
            return False, "cannot read the Pi supply state (vcgencmd)"
        if self.last_flags & 0xF:
            return False, f"Pi supply problem right now (throttled=0x{self.last_flags:x})"
        self.until, self.ended_reason = self._clock() + minutes * 60, ""
        return True, f"attended session started for {minutes} min"

    def end(self, reason="ended by owner"):
        if self.until:
            self.until, self.ended_reason = 0.0, reason

    def active(self) -> bool:
        if self.until and self._clock() >= self.until:
            self.end("session time is over")
        return bool(self.until)

    def remaining_s(self) -> int:
        return int(self.until - self._clock()) if self.active() else 0

    def check(self) -> str:
        """Call every few seconds. Ends the session on under-voltage; returns the reason or ''."""
        if not self.active():
            return ""
        self.last_flags = self._throttled()
        if self.last_flags is None or self.last_flags & 0x1:
            reason = "Pi under-voltage" if self.last_flags else "Pi supply state unreadable"
            self.end(reason)
            return reason
        return ""

    def status(self) -> dict:
        return {"session_active": self.active(), "remaining_s": self.remaining_s(), "ended_reason": self.ended_reason,
                "throttled": None if self.last_flags is None else f"0x{self.last_flags:x}",
                "battery_percent": None, "note": "no battery readings exist in this build"}

eve3/protocol.py:
"""M02 - E1 serial framing shared with the Mega firmware.

Frame:  E1:<seq 1..65535>:<payload printable ASCII without '*' or ':'>*<CRC16-CCITT, 4 hex>\\n
"""
from __future__ import annotations
import re

MAX_FRAME = 195
TELEMETRY_FIELDS = 10   # cl,cc,cr,pir,homed,pan,tilt,head_busy,drive_active,latched


def crc16_ccitt(data: bytes, crc: int = 0xFFFF) -> int:
    for byte in data:
        crc ^= byte << 8
        for _ in range(8):
            crc = ((crc << 1) ^ 0x1021) & 0xFFFF if crc & 0x8000 else (crc << 1) & 0xFFFF
    return crc


def encode(seq: int, payload: str) -> bytes:
    if type(seq) is not int or not 1 <= seq <= 65535:
        raise ValueError("sequence must be 1..65535")
    if (not isinstance(payload, str) or not payload
            or any(ord(c) < 32 or ord(c) > 126 or c in "*:" for c in payload)):
        raise ValueError("invalid payload")
    core = f"E1:{seq}:{payload}".encode("ascii")
    frame = core + f"*{crc16_ccitt(core):04X}\n".encode("ascii")
    if len(frame) > MAX_FRAME:
        raise ValueError("frame too long")
    return frame


_RX = re.compile(rb"E1:([0-9]{1,5}):([ -)+-9;-~]+)\*([0-9a-fA-F]{4})\r?\n")


def decode(line: bytes) -> tuple[int, str]:
    if len(line) > MAX_FRAME or not line.endswith(b"\n"):
        raise ValueError("truncated or oversized frame")
    m = _RX.fullmatch(line)
    if not m:
        raise ValueError("malformed frame")
    seq = int(m[1])
    if not 1 <= seq <= 65535:
        raise ValueError("invalid sequence")
    if crc16_ccitt(line[:line.rfind(b"*")]) != int(m[3], 16):
        raise ValueError("CRC mismatch")
    return seq, m[2].decode("ascii")


def parse_telemetry(payload: str, pan_limit: int = 2048, tilt_limit: int = 2048) -> dict:
    v = payload.split(",")
    if v[0] != "T" or len(v) != TELEMETRY_FIELDS + 1:
        raise ValueError("unexpected telemetry schema")
    if not all(re.fullmatch(r"-?[0-9]{1,5}", x) for x in v[1:]):
        raise ValueError("telemetry field is not a small integer")
    a = [int(x) for x in v[1:]]
    if any(a[i] not in (0, 1) for i in (0, 1, 2, 3, 4, 7, 8, 9)):
        raise ValueError("telemetry flag out of range")
    if abs(a[5]) > pan_limit or abs(a[6]) > tilt_limit:
        raise ValueError("telemetry step out of range")
    return {"cliff_raw": tuple(a[0:3]), "pir": bool(a[3]), "homed": bool(a[4]), "pan": a[5], "tilt": a[6],
            "head_busy": bool(a[7]), "drive_active": bool(a[8]), "latched": bool(a[9])}

eve3/safety.py:
"""M05 - fail-closed safety gate. Every check must pass; anything missing or stale counts as unsafe.
All wheel and head commands go through here before they reach the Mega (which checks again itself)."""
from __future__ import annotations
import math, threading, time
from dataclasses import dataclass
from .config import POWER_FLAGS, missing_flags
from .sensors import Frame, valid_tof_mm


@dataclass(frozen=True)
class Verdict:
    ok: bool
    reason: str = ""


class SafetyGate:
    def __init__(self, cfg: dict, session, clock=time.monotonic):
        self.cfg, self.session, self._clock = cfg, session, clock
        self.stop_mm = float(cfg["drive"]["obstacle_stop_mm"])
        self.timeout_s = cfg["safety"]["sensor_timeout_ms"] / 1000
        self.max_tilt = float(cfg["safety"]["max_tilt_deg"])
        self.tof_range = tuple(cfg["sensors"]["tof_range_mm"])
        self.latched = ""
        self._lock = threading.RLock()

    def latch(self, reason: str):
        with self._lock:
            if not self.latched:
                self.latched = str(reason)[:120]

    def sensors_reason(self, frame: Frame, check_obstacle=True) -> str:
        now = self._clock()

        def fresh(t):
            return type(t) in (int, float) and math.isfinite(t) and 0 < t <= now and now - t <= self.timeout_s
        if not fresh(frame.cliff_at):
            return "cliff data stale or missing (Mega telemetry)"
        if not self.cfg["sensors"]["cliff_calibration"]["calibrated"]:
            return "cliff sensors not calibrated"
        if len(frame.cliff) != 3 or any(c is not False for c in frame.cliff):
            return "cliff"
        if not fresh(frame.tof_at):
            return "distance data stale or missing"
        if len(frame.tof_mm) != 3 or not all(valid_tof_mm(v, *self.tof_range) for v in frame.tof_mm):
            return "distance reading invalid or missing"
        if not fresh(frame.imu_at):
            return "tilt data stale or missing"
        tilt = frame.tilt_deg
        if type(tilt) not in (int, float) or not math.isfinite(tilt):
            return "tilt reading invalid or missing"
        if abs(tilt) > self.max_tilt:
            return "tilt"
        if check_obstacle and min(frame.tof_mm[0], frame.tof_mm[1]) < self.stop_mm:
            return "obstacle"
        return ""

    def _common(self, frame, link, flags, firmware_flag, check_obstacle) -> Verdict:
        with self._lock:
            if self.latched:
                return Verdict(False, f"latched: {self.latched} (fix the cause, then send clear)")
            missing = missing_flags(self.cfg, flags)
            if missing:
                return Verdict(False, "commissioning incomplete: " + ", ".join(missing))
            if self.cfg["firmware"].get(firmware_flag) is not True:
                return Verdict(False, f"firmware.{firmware_flag} is off")
            if not link.online():
                return Verdict(False, "Mega link offline")
            if not link.firmware_ok:
                return Verdict(False, "Mega firmware does not match this config (gen_header, compile, upload)")
            if not self.session.active():
                return Verdict(False, "no attended session (start one first)")
            reason = self.sensors_reason(frame, check_obstacle)
            if reason in ("cliff", "tilt"):
                self.latched = reason                     # remember why, even after the sensor recovers
            if reason:
                return Verdict(False, reason)
            if link.telemetry.get("latched") is not False:
                return Verdict(False, "Mega is latched (send clear)")
            return Verdict(True)

    def drive_verdict(self, frame, link, test=False) -> Verdict:
        flags = POWER_FLAGS + ("contained_ground_area",) + (() if test else ("drive_verified",))
        return self._common(frame, link, flags, "drive_enabled", True)

    def head_verdict(self, frame, link, test=False) -> Verdict:
        verdict = self._common(frame, link, POWER_FLAGS + (() if test else ("head_verified",)), "head_enabled", False)
        if verdict.ok and link.telemetry.get("drive_active") is not False:
            return Verdict(False, "wheels are moving")
        return verdict

    def clear(self, frame, link) -> Verdict:
        """Owner asks to re-arm after a stop. Only succeeds when everything reads safe and the Mega agrees."""
        with self._lock:
            if not link.online():
                return Verdict(False, "Mega link offline")
            if not link.firmware_ok:
                return Verdict(False, "Mega firmware does not match this config (gen_header, compile, upload)")
            reason = self.sensors_reason(frame, check_obstacle=False)
            if reason:
                return Verdict(False, reason)
            try:
                link.clear_stop()
            except Exception as exc:
                return Verdict(False, f"Mega refused clear: {exc}")
            self.latched = ""
            return Verdict(True, "cleared")

eve3/scheduler.py:
"""M15 - reminders and timers. Stored in memory (SQLite) so they survive a restart."""
from __future__ import annotations
import time

MAX_AHEAD_S = 7 * 24 * 3600


class Scheduler:
    def __init__(self, memory, clock=time.time, utc_offset_minutes=330):
        self.memory, self._clock, self.offset_s = memory, clock, utc_offset_minutes * 60

    def add_in(self, seconds, text) -> tuple[bool, str]:
        if type(seconds) not in (int, float) or not 5 <= seconds <= MAX_AHEAD_S:
            return False, "time must be between 5 seconds and 7 days"
        try:
            self.memory.add_reminder(self._clock() + seconds, text)
        except ValueError as exc:
            return False, str(exc)
        return True, "reminder saved"

    def add_at(self, hour, minute, text) -> tuple[bool, str]:
        if type(hour) is not int or type(minute) is not int or not (0 <= hour <= 23 and 0 <= minute <= 59):
            return False, "time must be HH:MM"
        now = self._clock()
        local_midnight = (now + self.offset_s) // 86400 * 86400 - self.offset_s
        due = local_midnight + hour * 3600 + minute * 60
        if due <= now:
            due += 86400
        return self.add_in(due - now, text) if due - now >= 5 else self.add_in(5, text)

    def next_due(self) -> dict | None:
        return self.memory.next_due(self._clock())

    def pending(self) -> list[dict]:
        now = self._clock()
        return [{"id": r["id"], "in_s": max(0, int(r["due"] - now)), "text": r["text"],
                 "announced": r["announced"]} for r in self.memory.pending_reminders()]

eve3/sensors.py:
"""M04 - sensors. 3x GY-530 VL53L0X (XSHUT BCM5/6/13 -> 0x30/0x31/0x32), MPU-6050 (0x68), and the three
digital TCRT5000 cliff modules + PIR that arrive through Mega telemetry.

Order of the ToF tuple: (front-left, front-right, rear). Order of cliff: (front-left, rear-centre, front-right).
A reading that is missing, stale or out of range is None / unsafe - nothing is ever invented.
Hardware libraries are imported only inside start() so everything else runs on a PC.
"""
from __future__ import annotations
import math, threading, time
from dataclasses import dataclass, replace, asdict


@dataclass(frozen=True)
class Frame:
    tof_mm: tuple = (None, None, None)
    tof_at: float = 0.0
    tilt_deg: float | None = None
    imu_at: float = 0.0
    cliff: tuple = (True, True, True)      # True = unsafe; the default fails closed
    cliff_raw: tuple = (None, None, None)
    cliff_at: float = 0.0
    pir: bool = False

    def dict(self):
        return asdict(self)


def valid_tof_mm(v, lo=30, hi=1000) -> bool:
    return type(v) in (int, float) and math.isfinite(v) and lo <= v <= hi


def decode_cliff(raw, edge_level, calibrated: bool) -> tuple:
    """A digital cliff channel is unsafe when it reads its edge level or an unexpected value."""
    if not calibrated or len(raw) != 3:
        return (True, True, True)
    return tuple(r not in (0, 1) or r == e for r, e in zip(raw, edge_level))


def calibrate_cliff(floor_rows, edge_rows) -> dict:
    """Needs >= 10 steady readings on the floor and >= 10 over an edge; every channel must flip."""
    for rows in (floor_rows, edge_rows):
        if len(rows) < 10 or any(len(r) != 3 or any(v not in (0, 1) for v in r) for r in rows):
            raise ValueError("need at least 10 rows of three 0/1 values for both floor and edge")
    levels = []
    for i, name in enumerate(("front-left", "rear-centre", "front-right")):
        floor, edge = {r[i] for r in floor_rows}, {r[i] for r in edge_rows}
        if len(floor) != 1 or len(edge) != 1 or floor == edge:
            raise ValueError(f"{name} cliff sensor: reading flickers or does not change between floor and edge "
                             "(adjust the threshold on that digital cliff module and repeat)")
        levels.append(next(iter(edge)))
    return {"calibrated": True, "edge_level": levels}


class ToFArray:
    def __init__(self, xshut=(5, 6, 13), addresses=(0x30, 0x31, 0x32)):
        self.xshut, self.addresses = tuple(xshut), tuple(addresses)
        self.sensors, self._lines, self.i2c = [], [], None

    def start(self):
        import board, busio, digitalio, adafruit_vl53l0x
        self.close()
        self.i2c = busio.I2C(board.SCL, board.SDA)
        for pin in self.xshut:
            line = digitalio.DigitalInOut(getattr(board, f"D{pin}"))
            line.switch_to_output(value=False)           # hold LOW = sensor off
            self._lines.append(line)
        time.sleep(0.02)
        for line, address in zip(self._lines, self.addresses):
            line.switch_to_input()                        # release; the board's own pull-up wakes it (never drive HIGH)
            time.sleep(0.02)
            sensor = adafruit_vl53l0x.VL53L0X(self.i2c, io_timeout_s=0.10)   # answers at the default 0x29
            sensor.set_address(address)
            self.sensors.append(sensor)

    def sample(self) -> tuple:
        if len(self.sensors) != 3:
            raise RuntimeError("ToF sensors not started")
        out = []
        for sensor in self.sensors:
            value = float(sensor.range)
            out.append(value if valid_tof_mm(value) else None)
        return tuple(out)

    def close(self):
        for line in self._lines:
            try:
                line.switch_to_output(value=False)
                line.deinit()
            except Exception:
                pass
        if self.i2c is not None:
            try:
                self.i2c.deinit()
            except Exception:
                pass
        self._lines, self.sensors, self.i2c = [], [], None


def _s16(v):
    return v - 65536 if v & 0x8000 else v


class MPU6050:
    def __init__(self, bus_factory=None, address=0x68, inverted=False):
        self._bus_factory, self.address, self.bus = bus_factory, address, None
        self.inverted = inverted                      # True if the board is mounted upside down

    def start(self):
        if self._bus_factory is None:
            import smbus2
            self._bus_factory = lambda: smbus2.SMBus(1)
        self.close()
        self.bus = self._bus_factory()
        if self.bus.read_byte_data(self.address, 0x75) not in (0x68, 0x69, 0x70, 0x72):
            raise RuntimeError("MPU6050 WHO_AM_I mismatch")
        self.bus.write_byte_data(self.address, 0x6B, 0x00)     # wake
        self.bus.write_byte_data(self.address, 0x1C, 0x00)     # +-2 g
        time.sleep(0.05)

    def sample(self) -> float:
        b = self.bus.read_i2c_block_data(self.address, 0x3B, 6)
        if len(b) != 6:
            raise RuntimeError("short MPU6050 read")
        ax, ay, az = (_s16((b[i] << 8) | b[i + 1]) / 16384.0 for i in (0, 2, 4))
        norm = math.sqrt(ax * ax + ay * ay + az * az)
        if not 0.5 <= norm <= 1.5:
            raise ValueError("acceleration is not close to 1 g (moving, or bad read)")
        return math.degrees(math.atan2(math.hypot(ax, ay), -az if self.inverted else az))

    def close(self):
        if self.bus is not None:
            try:
                self.bus.close()
            except Exception:
                pass
        self.bus = None


class SensorHub:
    """Holds the latest frame. Writers: the sensor thread (ToF, IMU) and the Mega reader (cliff, PIR)."""

    def __init__(self, cliff_calibration: dict | None = None):
        cal = cliff_calibration or {}
        self.edge_level = tuple(cal.get("edge_level", (0, 0, 0)))
        self.calibrated = cal.get("calibrated") is True
        self._frame = Frame()
        self._lock = threading.Lock()

    def _set(self, **changes):
        with self._lock:
            self._frame = replace(self._frame, **changes)

    def update_tof(self, tof, at=None):
        self._set(tof_mm=tuple(tof), tof_at=time.monotonic() if at is None else at)

    def update_imu(self, tilt, at=None):
        self._set(tilt_deg=tilt, imu_at=time.monotonic() if at is None else at)

    def update_mega(self, telemetry: dict, at=None):
        raw = tuple(telemetry["cliff_raw"])
        self._set(cliff=decode_cliff(raw, self.edge_level, self.calibrated), cliff_raw=raw,
                  cliff_at=time.monotonic() if at is None else at, pir=bool(telemetry["pir"]))

    def snapshot(self) -> Frame:
        with self._lock:
            return self._frame


class SensorReader:
    """Polls ToF + IMU. A failed device is restarted every `retry_s`; while it is down its data goes stale,
    which the safety gate treats as unsafe."""

    def __init__(self, hub: SensorHub, tof, imu, retry_s: float = 5.0, clock=time.monotonic):
        self.hub, self.clock, self.retry_s = hub, clock, retry_s
        self.devices = {"tof": [tof, False, -1e9, "not started"], "imu": [imu, False, -1e9, "not started"]}

    def _poll_one(self, name, publish, missing):
        dev = self.devices[name]
        device, started, last_try, _ = dev
        if not started:
            if self.clock() - last_try < self.retry_s:
                return
            dev[2] = self.clock()
            try:
                device.start()
                dev[1], dev[3] = True, ""
            except Exception as exc:
                dev[3] = f"{type(exc).__name__}: {exc}"[:160]
                return
        try:
            publish(device.sample())
            dev[3] = ""
        except ValueError as exc:                       # keep the device, invalidate the sample
            publish(missing, at=0)
            dev[3] = str(exc)[:160]
        except Exception as exc:                        # bus error: restart the device later
            publish(missing, at=0)
            dev[1], dev[2], dev[3] = False, self.clock(), f"{type(exc).__name__}: {exc}"[:160]
            try:
                device.close()
            except Exception:
                pass

    def poll(self):
        self._poll_one("tof", self.hub.update_tof, (None, None, None))
        self._poll_one("imu", self.hub.update_imu, None)

    def status(self) -> dict:
        return {name: {"ok": d[1] and not d[3], "error": d[3]} for name, d in self.devices.items()}

    def close(self):
        for dev in self.devices.values():
            try:
                dev[0].close()
            except Exception:
                pass
            dev[1] = False

eve3/server.py:
"""M01 - local web server (Python standard library only): the face, a control page and a small JSON API.

Default: listens on 127.0.0.1 only. If the owner sets network.host to 0.0.0.0 the home LAN can reach it;
then every request except the face page itself needs the token. Commands ALWAYS need the token.
"""
from __future__ import annotations
import hmac, ipaddress, json, threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from zipfile import ZipFile
from .expressions import CLIPS, WEB
from urllib.parse import parse_qs, urlparse

MAX_BODY = 4096
MAX_HOME_BODY = 32768
PAGES = {"/": "face.html", "/control": "control.html", "/expressions": "expressions.html", "/home": "home.html"}
EXPRESSION_ASSETS = {
    "/home.css": ("home.css", "text/css"),
    "/home.js": ("home.js", "text/javascript"),
    "/eva-face-art.js": ("eva-face-art.js", "text/javascript"),
    "/expression-audio.js": ("expression-audio.js", "text/javascript"),
    "/expression-assets.json": ("expressions.json", "application/json"),
}


def host_allowed(host_header: str) -> bool:
    """Blocks DNS-rebinding: the browser must be addressing this Pi by IP, localhost or *.local."""
    host = (host_header or "").rsplit(":", 1)[0].strip("[]").lower()
    if host in ("localhost",) or host.endswith(".local"):
        return True
    try:
        ipaddress.ip_address(host)
        return True
    except ValueError:
        return False


def make_handler(runtime):
    class Handler(BaseHTTPRequestHandler):
        server_version = "EVE"
        sys_version = ""
        protocol_version = "HTTP/1.1"

        def log_message(self, *args):                    # no access log: nothing private ends up on disk
            pass

        def _send(self, code, body: bytes, ctype="application/json"):
            self.send_response(code)
            self.send_header("Content-Type", ctype if ctype.startswith("audio/") else ctype + "; charset=utf-8")
            self.send_header("Content-Length", str(len(body)))
            self.send_header("Cache-Control", "no-store")
            self.send_header("X-Content-Type-Options", "nosniff")
            self.send_header("X-Frame-Options", "DENY")
            self.send_header("Content-Security-Policy", "default-src 'self' 'unsafe-inline'; connect-src 'self'; media-src 'self' blob:")
            self.end_headers()
            self.wfile.write(body)

        def _json(self, code, obj):
            self._send(code, json.dumps(obj, ensure_ascii=False).encode("utf-8"))

        def _local(self) -> bool:
            return self.client_address[0] in ("127.0.0.1", "::1")

        def _token_ok(self, query=None) -> bool:
            given = self.headers.get("X-EVE-Token") or ((query or {}).get("t") or [""])[0]
            return isinstance(given, str) and hmac.compare_digest(given.encode(), runtime.token.encode())

        def do_GET(self):
            if not host_allowed(self.headers.get("Host", "")):
                return self._json(403, {"ok": False, "message": "bad host"})
            url = urlparse(self.path)
            if url.path in PAGES:
                return self._send(200, (WEB / PAGES[url.path]).read_bytes(), "text/html")
            if url.path in EXPRESSION_ASSETS:
                file, mime = EXPRESSION_ASSETS[url.path]
                return self._send(200, (WEB / file).read_bytes(), mime)
            if url.path.startswith("/sfx/"):
                name = url.path.removeprefix("/sfx/")
                if name.endswith(".wav") and name[:-4] in CLIPS:
                    with ZipFile(WEB / "expression-sounds.zip") as pack:
                        return self._send(200, pack.read(name), "audio/wav")
            if url.path == "/api/audio-priority":
                if not self._token_ok():
                    return self._json(401, {"ok": False, "message": "token required"})
                return self._json(200, runtime.audio_priority())
            if url.path == "/api/status":
                if not (self._local() or self._token_ok(parse_qs(url.query))):
                    return self._json(401, {"ok": False, "message": "token required"})
                return self._json(200, runtime.status())
            self._json(404, {"ok": False, "message": "not found"})

        def do_POST(self):
            if not host_allowed(self.headers.get("Host", "")):
                return self._json(403, {"ok": False, "message": "bad host"})
            path = urlparse(self.path).path
            if path not in ("/api/command", "/api/home-command"):
                return self._json(404, {"ok": False, "message": "not found"})
            if not self._token_ok():
                return self._json(401, {"ok": False, "message": "token required"})
            try:
                length = int(self.headers.get("Content-Length", ""))
            except ValueError:
                return self._json(411, {"ok": False, "message": "length required"})
            limit = MAX_HOME_BODY if path == "/api/home-command" else MAX_BODY
            if not 0 < length <= limit:
                return self._json(413, {"ok": False, "message": "request too large"})
            try:
                body = json.loads(self.rfile.read(length).decode("utf-8"))
                name, args = body["name"], body.get("args", {})
            except (ValueError, KeyError, TypeError, UnicodeError):
                return self._json(400, {"ok": False, "message": "bad JSON"})
            if path == "/api/home-command" and (not isinstance(name, str) or not name.startswith("home.")):
                return self._json(400, {"ok": False, "message": "home command required"})
            ok, message = runtime.execute(name, args, source="owner")
            self._json(200, {"ok": bool(ok), "message": message})

    return Handler


def serve(runtime, host: str, port: int) -> ThreadingHTTPServer:
    server = ThreadingHTTPServer((host, port), make_handler(runtime))
    server.daemon_threads = True
    threading.Thread(target=server.serve_forever, name="eve3-http", daemon=True).start()
    return server

eve3/sim.py:
"""A small pretend Mega (serial-like object) for tests and for `python -m eve3 --sim` on a PC.
It follows the same rules as the firmware closely enough to exercise the Pi side; the real firmware
logic is tested separately in tests/test_firmware_sim.py."""
from __future__ import annotations
import queue, threading, time
from .protocol import decode, encode


class FakeMega:
    def __init__(self, firmware_id="sim000000000", drive_enabled=True, head_enabled=True):
        self.firmware_id, self.drive_enabled, self.head_enabled = firmware_id, drive_enabled, head_enabled
        self.rx: queue.Queue = queue.Queue()
        self.cliff = [1, 1, 1]            # 1 = floor seen (safe) with edge_level 0
        self.edge_level = [0, 0, 0]
        self.pir = 0
        self.latched, self.homed = True, False
        self.pan = self.tilt = 0
        self.left = self.right = 0
        self.last_hb = self.last_drive = 0.0
        self.last_seq = 0
        self.closed = False
        self.silent = False               # True = stop answering (simulates a pulled cable)
        self.log: list[str] = []
        self._tel_at = 0.0
        self._lock = threading.Lock()

    def _cliff_safe(self):
        return all(c != e for c, e in zip(self.cliff, self.edge_level))

    def _hb_ok(self):
        return time.monotonic() - self.last_hb < 0.35

    def _reply(self, seq, payload):
        if not self.silent:
            self.rx.put(encode(seq, payload))

    def write(self, data: bytes) -> int:
        if self.closed:
            raise IOError("closed")
        try:
            seq, p = decode(data)
        except ValueError:
            return len(data)
        with self._lock:
            self.log.append(p)
            self.last_seq = seq
            if p == "SYNC":
                self.latched, self.homed, self.left, self.right = True, False, 0, 0
                self._reply(seq, f"ACK,{self.firmware_id}")
            elif p == "HB":
                self.last_hb = time.monotonic(); self._reply(seq, "ACK")
            elif p == "STOP":
                self.latched, self.homed, self.left, self.right = True, False, 0, 0; self._reply(seq, "ACK")
            elif p == "HEADSTOP":
                self.homed = False; self._reply(seq, "ACK")
            elif p == "CLEAR":
                ok = self._hb_ok() and self._cliff_safe()
                if ok:
                    self.latched = False
                self._reply(seq, "ACK" if ok else "ERR,UNSAFE")
            elif p == "HOMESET":
                ok = self.head_enabled and not self.latched and self._hb_ok()
                if ok:
                    self.homed, self.pan, self.tilt = True, 0, 0
                self._reply(seq, "ACK" if ok else "ERR,UNSAFE")
            elif p.startswith("DRIVE,"):
                l, r = (int(x) for x in p.split(",")[1:])
                if l == 0 and r == 0:
                    self.left = self.right = 0; self._reply(seq, "ACK")
                elif self.drive_enabled and not self.latched and self._hb_ok() and self._cliff_safe():
                    self.left, self.right, self.last_drive = l, r, time.monotonic(); self._reply(seq, "ACK")
                else:
                    self._reply(seq, "ERR,UNSAFE")
            elif p.startswith("HEAD,"):
                pan, tilt = (int(x) for x in p.split(",")[1:])
                if self.head_enabled and self.homed and not self.latched and self._hb_ok():
                    self.pan, self.tilt = pan, tilt; self._reply(seq, "ACK")
                else:
                    self._reply(seq, "ERR,UNSAFE")
            else:
                self._reply(seq, "ERR,CMD")
        return len(data)

    def _tick(self):
        with self._lock:
            now = time.monotonic()
            if not self.latched and (not self._hb_ok() or not self._cliff_safe()):
                self.latched, self.homed, self.left, self.right = True, False, 0, 0
            if (self.left or self.right) and now - self.last_drive > 0.3:
                self.left = self.right = 0
            if now - self._tel_at >= 0.1 and self.last_seq and not self.silent:
                self._tel_at = now
                c = self.cliff
                self.rx.put(encode(self.last_seq, f"T,{c[0]},{c[1]},{c[2]},{self.pir},{int(self.homed)},{self.pan},"
                                                  f"{self.tilt},0,{int(bool(self.left or self.right))},{int(self.latched)}"))

    def read_until(self, _terminator=b"\n", _size=None) -> bytes:
        if self.closed:
            raise IOError("closed")
        self._tick()
        try:
            return self.rx.get(timeout=0.02)
        except queue.Empty:
            return b""

    def reset_input_buffer(self):
        pass

    def close(self):
        self.closed = True

eve3/touch.py:
"""M09 - two TTP223 touch pads on the Pi: head (BCM27) and back (BCM22), momentary, active high.
Head pat = happy. Back tap = wake / listen. Back hold = STOP."""
from __future__ import annotations


class TouchPads:
    def __init__(self, cfg, on_head, on_back_tap, on_back_hold, button_factory=None):
        t = cfg["touch"]
        self.enabled = t["enabled"] is True
        self.pins = (int(t["head_gpio"]), int(t["back_gpio"]))
        self.hold_s = float(t["hold_stop_s"])
        self.on_head, self.on_back_tap, self.on_back_hold = on_head, on_back_tap, on_back_hold
        self._factory = button_factory
        self._buttons = []
        self._held = False
        self.error = "not started"

    def start(self):
        if not self.enabled:
            self.error = "switched off in config"
            return
        try:
            factory = self._factory
            if factory is None:
                from gpiozero import Button
                factory = lambda pin, hold: Button(pin, pull_up=None, active_state=True, bounce_time=0.05, hold_time=hold)
            head, back = factory(self.pins[0], self.hold_s), factory(self.pins[1], self.hold_s)
            head.when_pressed = self.on_head
            back.when_held = self._back_held
            back.when_released = self._back_released
            self._buttons, self.error = [head, back], ""
        except Exception as exc:
            self.error = f"{type(exc).__name__}: {exc}"[:120]

    def _back_held(self):
        self._held = True
        self.on_back_hold()

    def _back_released(self):
        if not self._held:
            self.on_back_tap()
        self._held = False

    def close(self):
        for button in self._buttons:
            try:
                button.close()
            except Exception:
                pass
        self._buttons = []

eve3/voice.py:
"""M13 - local voice. The normal ALSA path takes turns. The optional paired echo-cancel path
uses the Pi's local desktop audio server. Temporary recognition clips live in RAM under /dev/shm."""
from __future__ import annotations
import array, os, queue, shlex, subprocess, tempfile, threading, time, wave

VOICES = {"en": "en", "hi": "hi", "mr": "mr"}
ECHO_SOURCE = "eve_echo_capture"
ECHO_SINK = "eve_echo_playback"


def audio_server() -> str:
    # Explicit Unix socket keeps the microphone on this host even if PULSE_SERVER is set.
    return f"--server=unix:/run/user/{os.getuid()}/pulse/native"


def check_echo_route(run=subprocess.run):
    def rows(kind):
        result = run(["pactl", audio_server(), "list", "short", kind], timeout=2,
                     text=True, capture_output=True, check=True)
        return [line.split("\t") for line in result.stdout.splitlines()]

    try:
        sources = {row[1] for row in rows("sources") if len(row) > 1}
        sinks = {row[1] for row in rows("sinks") if len(row) > 1}
        for row in rows("modules"):
            if len(row) < 3 or row[1] != "module-echo-cancel":
                continue
            options = dict(option.split("=", 1) for option in shlex.split(row[2]) if "=" in option)
            capture, playback = options.get("source_master", ""), options.get("sink_master", "")
            if (options.get("aec_method") == "webrtc" and options.get("source_name") == ECHO_SOURCE
                    and options.get("sink_name") == ECHO_SINK and {ECHO_SOURCE, capture} <= sources
                    and {ECHO_SINK, playback} <= sinks and capture != ECHO_SOURCE
                    and not capture.endswith(".monitor") and playback != ECHO_SINK):
                return
    except (OSError, subprocess.SubprocessError, ValueError):
        pass
    raise RuntimeError("local WebRTC echo route unavailable; see optional voice setup (M13)")


def clean_speech(text, limit=300) -> str:
    text = " ".join("".join(ch if ch.isprintable() else " " for ch in str(text)).split())
    return text[:limit]


class Speaker:
    def __init__(self, cfg, run=subprocess.run):
        v = cfg["voice"]
        self.enabled, self.command, self.speed = v["tts_enabled"] is True, v["tts_command"], int(v["tts_speed"])
        self.echo_cancel = v["echo_cancel_enabled"]
        self._run = run
        self._queue: queue.Queue = queue.Queue(maxsize=5)
        self.speaking = False
        self.last_error = ""
        self.quiet_until = 0.0
        self._stop = threading.Event()
        self._thread = None

    def start(self):
        self._stop.clear()
        self._thread = threading.Thread(target=self._loop, name="eve3-speaker", daemon=True)
        self._thread.start()

    def say(self, text, lang="en", on_done=None) -> bool:
        text = clean_speech(text)
        if not self.enabled or not text or self._stop.is_set():
            return False
        try:
            self._queue.put_nowait((text, VOICES.get(lang, "en"), on_done))
            return True
        except queue.Full:
            return False                                # drop rather than fall behind

    @property
    def speech_pending(self):
        return bool(self._queue.unfinished_tasks)

    def speak_now(self, text, voice):
        self.speaking = True
        try:
            # list arguments + "--": the text can never be read as an option or a shell command
            args = [self.command, "-v", voice, "-s", str(self.speed)]
            if self.echo_cancel:
                check_echo_route(self._run)
                args.append("--stdout")
            result = self._run([*args, "--", text], timeout=30, check=False, capture_output=True)
            code = getattr(result, "returncode", 0)
            self.last_error = f"speech command exited {code}" if code else ""
            if self.echo_cancel and not code:
                result = self._run(["paplay", audio_server(), f"--device={ECHO_SINK}"], input=result.stdout,
                                   timeout=30, check=False, capture_output=True)
                if result.returncode:
                    self.last_error = "echo-cancel playback failed"
        except RuntimeError as exc:
            self.last_error = str(exc)
        except Exception as exc:
            self.last_error = type(exc).__name__
        finally:
            self.quiet_until = time.monotonic() + 0.5
            self.speaking = False
        return not self.last_error

    def _loop(self):
        while not self._stop.is_set():
            try:
                text, voice, complete = self._queue.get(timeout=0.2)
            except queue.Empty:
                continue
            try:
                success = not self._stop.is_set() and self.speak_now(text, voice)
                if complete:
                    complete(success)
            finally:
                self._queue.task_done()

    def stop(self):
        self._stop.set()
        while not self._queue.empty():
            try:
                self._queue.get_nowait()
                self._queue.task_done()
            except queue.Empty:
                break


def rms(pcm: bytes) -> float:
    samples = array.array("h")
    samples.frombytes(pcm[:len(pcm) // 2 * 2])
    if not samples:
        return 0.0
    return (sum(s * s for s in samples) / len(samples)) ** 0.5


class Segmenter:
    """Cuts a stream of 16-bit mono chunks into utterances: starts on a loud chunk, ends after a pause."""

    def __init__(self, threshold=500.0, chunk_s=0.1, silence_s=0.7, max_s=8.0, min_s=0.3, pre_chunks=2):
        self.threshold = float(threshold)
        self.silence_chunks = max(1, round(silence_s / chunk_s))
        self.max_chunks, self.min_chunks, self.pre_chunks = round(max_s / chunk_s), round(min_s / chunk_s), pre_chunks
        self.reset()

    def reset(self):
        self._pre, self._buf, self._quiet, self._loud = [], [], 0, 0

    def feed(self, chunk: bytes) -> bytes | None:
        loud = rms(chunk) >= self.threshold
        if not self._buf:
            if not loud:
                self._pre = (self._pre + [chunk])[-self.pre_chunks:]
                return None
            self._buf, self._pre, self._quiet, self._loud = self._pre + [chunk], [], 0, 1
            return None
        self._buf.append(chunk)
        self._loud += loud
        self._quiet = 0 if loud else self._quiet + 1
        if self._quiet >= self.silence_chunks or len(self._buf) >= self.max_chunks:
            out, loud_count = b"".join(self._buf), self._loud
            self.reset()
            return out if loud_count >= self.min_chunks else None    # a click or bump is not speech
        return None


def transcribe(cfg, pcm: bytes, run=subprocess.run, shm="/dev/shm") -> str:
    """whisper.cpp on a clip that exists only in RAM-backed /dev/shm and is removed afterwards."""
    v = cfg["voice"]
    root = cfg["_root"]
    if not os.path.isdir(shm):
        raise RuntimeError("RAM audio directory unavailable; refusing to write microphone audio to disk")
    fd, path = tempfile.mkstemp(suffix=".wav", prefix="eve-", dir=shm)
    try:
        with os.fdopen(fd, "wb") as handle, wave.open(handle, "wb") as wav:
            wav.setnchannels(1); wav.setsampwidth(2); wav.setframerate(int(v["sample_rate"])); wav.writeframes(pcm)
        result = run([os.path.join(root, v["stt_command"]), "-m", os.path.join(root, v["stt_model"]), "-f", path,
                      "-l", str(v["stt_language"]), "-nt", "-np", "-t", "3"],
                     capture_output=True, text=True, timeout=v["stt_timeout_s"], check=False)
        if getattr(result, "returncode", 0) != 0:
            raise RuntimeError("speech recognition command failed")
        text = " ".join(result.stdout.split())
        return "" if text.startswith(("[", "(")) else text[:400]         # "[BLANK_AUDIO]", "(music)" etc.
    finally:
        try:
            os.unlink(path)
        except OSError:
            pass


class Listener:
    """Microphone thread. Calls on_text(text) for each understood utterance."""

    def __init__(self, cfg, on_text, is_speaking, popen=subprocess.Popen, transcriber=transcribe):
        self.cfg, self.on_text, self.is_speaking = cfg, on_text, is_speaking
        self._popen, self._transcribe = popen, transcriber
        v = cfg["voice"]
        self.rate = int(v["sample_rate"])
        self.echo_cancel = v["echo_cancel_enabled"]
        self.chunk_bytes = self.rate // 10 * 2
        self.segmenter = Segmenter(v["vad_rms"], 0.1, v["silence_s"], v["max_utterance_s"])
        self.listening = False
        self.last_error = ""
        self.level = 0.0
        self._stop = threading.Event()
        self._thread = None
        self._proc = None

    def start(self):
        self._stop.clear()
        self._thread = threading.Thread(target=self._loop, name="eve3-listener", daemon=True)
        self._thread.start()

    def _loop(self):
        v = self.cfg["voice"]
        while not self._stop.is_set():
            failed = False
            try:
                if self.echo_cancel:
                    check_echo_route()
                    args = ["parec", audio_server(), f"--device={ECHO_SOURCE}", "--raw", "--format=s16le",
                            f"--rate={self.rate}", "--channels=1"]
                else:
                    args = ["arecord", "-q", "-D", str(v["capture_device"]), "-f", "S16_LE", "-r", str(self.rate),
                            "-c", "1", "-t", "raw"]
                self._proc = self._popen(args, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL)
                self.listening, self.last_error = True, ""
                while not self._stop.is_set():
                    chunk = self._proc.stdout.read(self.chunk_bytes)
                    if not chunk:
                        raise IOError("microphone stream ended")
                    if self.handle_chunk(chunk):
                        break                    # reopen the device after inference; discard queued audio
            except Exception as exc:
                self.last_error = f"{type(exc).__name__}: {exc}"[:120]
                failed = True
            finally:
                self.listening = False
                self._kill()
            if failed:
                self._stop.wait(5)               # retry later; never spin

    def handle_chunk(self, chunk: bytes):
        if not self.echo_cancel and self.is_speaking():
            self.segmenter.reset()                       # half-duplex: ignore the robot's own voice
            return
        self.level = rms(chunk)
        utterance = self.segmenter.feed(chunk)
        if utterance:
            self._kill()                         # the capture buffer cannot accumulate while recognition runs
            text = self._transcribe(self.cfg, utterance)
            if text and not self._stop.is_set() and (self.echo_cancel or not self.is_speaking()):
                self.on_text(text)
            return True

    def _kill(self):
        proc, self._proc = self._proc, None
        if proc is not None:
            try:
                proc.kill()
                proc.wait(timeout=2)
            except Exception:
                pass

    def stop(self):
        self._stop.set()
        self._kill()

